from itertools import permutations
from fractions import Fraction

def compose(a, b):
    return tuple(a[b[i]] for i in range(3))

def inverse(a):
    inv = [0]*3
    for i in range(3):
        inv[a[i]] = i
    return tuple(inv)

def commutator(a, b):
    return compose(compose(a, b), compose(inverse(a), inverse(b)))

S3 = list(permutations(range(3)))
identity = (0, 1, 2)

def count_hom_brute_force(g):
    if g == 1:
        return sum(1 for a in S3 for b in S3 if commutator(a, b) == identity)
    if g == 2:
        count = 0
        for a1 in S3:
            for b1 in S3:
                c1 = commutator(a1, b1)
                for a2 in S3:
                    for b2 in S3:
                        if compose(c1, commutator(a2, b2)) == identity:
                            count += 1
        return count
    raise ValueError('g too large for brute force')

def formula(g):
    return 2 * (6**(2*g - 1) + 3**(2*g - 1))

def mednykh_exact(g):
    """Mednykh formula using exact rational arithmetic.
    N(g) = |G|^{2g-1} * sum_{rho in Irr(G)} (dim rho)^{2-2g}
    For S_3: dims = [1, 1, 2], |G| = 6."""
    dims = [1, 1, 2]
    s = sum(Fraction(1, d**(2*g - 2)) for d in dims)
    return int(Fraction(6**(2*g - 1), 1) * s)

# Brute force checks for g=1,2
for g in [1, 2]:
    bf = count_hom_brute_force(g)
    fm = formula(g)
    assert bf == fm, f'Mismatch at g={g}: brute_force={bf}, formula={fm}'
    print(f'g={g}: brute_force={bf}, formula={fm} -- MATCH')

# Exact Mednykh vs simplified formula for g=1..30
for g in range(1, 31):
    m = mednykh_exact(g)
    f = formula(g)
    assert m == f, f'Mismatch at g={g}: mednykh={m}, formula={f}'

# Verify the algebraic identity: 6^{2g-1}/4^{g-1} = 2*3^{2g-1}
for g in range(1, 31):
    lhs = Fraction(6**(2*g-1), 4**(g-1))
    rhs = 2 * 3**(2*g-1)
    assert lhs == rhs, f'Algebra identity failed at g={g}'

print('All verification checks passed.')
print('Answer: N(g) = 2*(6^{2g-1} + 3^{2g-1})')
